<script lang="ts">
 import {onDestroy} from 'svelte';
 import {SKILLS,LESSONS,topicScore,scoreBand,type CzechState} from '$lib/czech/study';
 import {readPracticeHistory} from '$lib/czech/repository';
 import {progressHistory,recordedVocabulary,type PracticeLog} from '$lib/czech/progress';
 export let uid:string;
 export let state:CzechState;
 export let onchoose:(id:string)=>void;
 let history:PracticeLog[]=[],loadedKey='',request=0,loading=false,error='',metric:'vocabulary'|'skills'='vocabulary';
 $: if(uid && loadedKey!==`${uid}:${state.practiceCount}`)load();
 async function load(){const id=++request,owner=uid;loadedKey=`${owner}:${state.practiceCount}`;loading=true;error='';if(!state.practiceCount){history=[];loading=false;return;}try{const value=await readPracticeHistory(owner);if(id===request)history=value;}catch(e){if(id===request)error='Could not load the chart history. Your saved progress is unchanged.';}finally{if(id===request)loading=false;}}
 onDestroy(()=>request++);
 $: days=progressHistory(history);
 $: vocabulary=recordedVocabulary(history,state.vocabulary??[]);
 let wordSearch='';
 $: visibleWords=[...vocabulary].filter(v=>`${v.term} ${v.meaning}`.toLocaleLowerCase().includes(wordSearch.toLocaleLowerCase())).sort((a,b)=>b.lastSeenAt.localeCompare(a.lastSeenAt)).slice(0,100);
 $: words=vocabulary.filter(v=>v.kind==='word').length;
 $: phrases=vocabulary.filter(v=>v.kind==='phrase').length;
 $: recalled=vocabulary.filter(v=>v.status==='recalled').length;
 $: covered=LESSONS.filter(l=>topicScore(state,l.id)!==undefined).length;
 $: chartDays=metric==='skills'?days.filter(d=>d.assessed>0):days;
 $: maximum=metric==='skills'?4:Math.max(1,...chartDays.map(d=>d.words+d.phrases));
 const x=(i:number,length:number)=>length===1?320:28+584*(Date.parse(chartDays[i].date)-Date.parse(chartDays[0].date))/(Date.parse(chartDays[length-1].date)-Date.parse(chartDays[0].date));
 const y=(n:number,max:number)=>122-n/max*100;
 $: points=chartDays.map((d,i)=>`${x(i,chartDays.length)},${y(metric==='skills'?d.average:d.words+d.phrases,maximum)}`).join(' ');
 $: recallPoints=chartDays.map((d,i)=>`${x(i,chartDays.length)},${y(d.recalled,maximum)}`).join(' ');
</script>
<section class="progress" aria-label="Czech progress">
 <div class="progress-heading"><div><h2>Your Czech is growing.</h2><p>Keep returning to familiar topics in richer situations. Nothing ends at a level.</p></div><div class="numbers"><span><b>{words}</b> words recorded</span><span><b>{phrases}</b> phrases recorded</span><span><b>{recalled}</b> independently recalled</span><span><b>{covered}/{LESSONS.length}</b> topics explored</span></div></div>
 <div class="map-head"><h3>Conversation map</h3><span>Each strip: listening · speaking · reading · writing</span></div>
 <div class="map">{#each LESSONS as l}<button class={`band-${scoreBand(topicScore(state,l.id))}`} on:click={()=>onchoose(l.id)} aria-label={`Practise ${l.title}`} title={`${l.track}: ${l.title}; ${Object.keys(state.assessments[l.id]??{}).length}/4 skills assessed`}><span>{l.title}</span><small>{l.track} · {Object.keys(state.assessments[l.id]??{}).length}/4 assessed</small><div class="strips">{#each SKILLS as skill}<i class={`band-${scoreBand(state.assessments[l.id]?.[skill]?.score)}`} title={`${skill}: ${state.assessments[l.id]?.[skill]?.score??'not assessed'}`}></i>{/each}</div></button>{/each}</div>
 <div class="legend"><span><i class="band-unassessed"></i>Not assessed</span><span><i class="band-starting"></i>Starting</span><span><i class="band-building"></i>Needs help</span><span><i class="band-developing"></i>Developing</span><span><i class="band-independent"></i>Independent</span><span><i class="band-confident"></i>Robust for this task</span></div>
 <div class="chart-head"><h3>Progress over time</h3><div role="group" aria-label="Chart metric"><button aria-pressed={metric==='vocabulary'} on:click={()=>metric='vocabulary'}>Vocabulary</button><button aria-pressed={metric==='skills'} on:click={()=>metric='skills'}>Skills</button></div></div>
 {#if loading}<p role="status">Loading your recorded history…</p>{:else if error}<p role="alert">{error} <button on:click={load}>Retry chart</button></p>{:else if days.length && (metric==='skills'?days.some(d=>d.assessed>0):days.some(d=>d.words+d.phrases>0))}
 <svg viewBox="0 0 640 152" role="img" aria-label={metric==='skills'?'Average recorded skill rating over time, out of four':'Recorded Czech words and phrases over time; green line shows independent recall'}><line x1="28" x2="612" y1="122" y2="122"/><line x1="28" x2="612" y1="22" y2="22"/><text x="4" y="126">0</text><text x="4" y="26">{maximum}</text><polyline points={points} class="total"/>{#if metric==='vocabulary'}<polyline points={recallPoints} class="recall"/>{/if}{#each chartDays as d,i}<circle cx={x(i,chartDays.length)} cy={y(metric==='skills'?d.average:d.words+d.phrases,maximum)} r="3"><title>{d.date}: {metric==='skills'?`${d.average.toFixed(1)}/4 (${d.assessed} assessed skills)`:`${d.words} words, ${d.phrases} phrases; ${d.recalled} independently recalled`}</title></circle>{/each}<text x="28" y="148">{chartDays[0].date}</text><text x="612" y="148" text-anchor="end">{chartDays[chartDays.length-1].date}</text></svg>
 <p class="chart-note">{metric==='vocabulary'?'Purple: recorded words + phrases. Green: independently recalled items. Repeated entries count once. This is your recorded vocabulary, not an estimate of everything you know.':'Average of observed skill ratings. Unassessed skills stay blank; harder tasks and a changing topic mix can lower this average. A 4/4 is not course completion.'}</p>
 <details><summary>Show recorded chart values</summary><div class="table-wrap"><table><thead><tr><th>Date</th><th>Words</th><th>Phrases</th><th>Recalled</th><th>Skills /4</th></tr></thead><tbody>{#each days as day}<tr><td>{day.date}</td><td>{day.words}</td><td>{day.phrases}</td><td>{day.recalled}</td><td>{day.assessed?day.average.toFixed(1):'—'}</td></tr>{/each}</tbody></table></div></details>
 {:else}<div class="empty">{metric==='vocabulary'?'Your first vocabulary entries will start this curve. New prompts ask the tutor to record only words and phrases actually practised.':'Your first assessed practice will start this curve.'}</div>{/if}
 {#if vocabulary.length}<details class="word-list"><summary>Your recorded vocabulary ({vocabulary.length})</summary><label>Find a word or meaning<input bind:value={wordSearch} type="search" placeholder="Czech or German…"/></label><p>Up to 100 matching entries shown. All recorded items count towards your progress.</p>{#each visibleWords as word}<div><span lang="cs"><b>{word.term}</b> · {word.meaning}</span><small>{word.kind} · {word.status==='recalled'?'independent recall':word.status==='needs-review'?'needs review':'introduced'} · {word.evidence}</small></div>{/each}</details>{/if}
</section>
<style>
 .word-list label{display:grid;gap:8px;margin:12px 0;font-size:.8rem}.word-list input{font:inherit;font-size:16px;color:#edf0f6;background:#101620;border:1px solid #3c4658;border-radius:8px;padding:10px;min-width:0;max-width:100%;box-sizing:border-box}.progress{border:1px solid #303746;border-radius:14px;padding:24px;margin:24px 0 32px;background:#131923;color:#edf0f6}.progress-heading{display:flex;justify-content:space-between;gap:24px;align-items:flex-start}.progress h2{margin:0 0 8px;font-size:1.45rem;letter-spacing:-.02em}.progress p{font-size:.8rem;color:#a7afc1;line-height:1.6;max-width:65ch;margin:0}.numbers{display:grid;grid-template-columns:repeat(2,auto);gap:12px 24px;font-size:.7rem;color:#a7afc1;flex-shrink:0}.numbers b{display:block;color:#edf0f6;font-size:1.35rem;font-variant-numeric:tabular-nums}.map-head,.chart-head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:26px 0 12px}h3{font-size:.95rem;margin:0}.map-head>span{font-size:.7rem;color:#a7afc1}.map{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px}.map button{border:1px solid transparent;min-width:0;min-height:102px;border-radius:9px;text-align:left;display:flex;flex-direction:column;justify-content:space-between;gap:10px;padding:12px;color:#f4f5fa;cursor:pointer;font:inherit;font-size:.76rem;line-height:1.35;touch-action:manipulation;transition:border-color 120ms ease-out}.map small{font-size:.6rem;color:#e0e3eb}.band-unassessed{background:#303744}.band-starting{background:#783f55}.band-building{background:#855321}.band-developing{background:#6d6428}.band-independent{background:#246676}.band-confident{background:#286b50}.strips{display:flex;width:100%;gap:3px}.strips i{display:block;flex:1;height:6px;border:1px solid #b5bece66;border-radius:2px}.legend{display:flex;flex-wrap:wrap;gap:12px;margin-top:14px;font-size:.65rem;color:#bbc2d1}.legend span{display:flex;align-items:center;gap:5px}.legend i{width:10px;height:10px;border-radius:2px}.chart-head{border-top:1px solid #303746;padding-top:22px}.chart-head>div{display:flex;gap:4px}button{color:#dce0ec;background:#1d2532;border:1px solid #3c4658;border-radius:7px;min-height:40px;padding:8px 12px;cursor:pointer;font:inherit;font-size:.75rem}button[aria-pressed=true]{background:#413958;border-color:#9183bf}svg{display:block;width:100%;max-height:200px;overflow:visible;margin-top:12px}line{stroke:#303a4a;stroke-width:1}polyline{fill:none;stroke-width:2.5;stroke-linejoin:round;stroke-linecap:round}.total{stroke:#b4adff}.recall{stroke:#7bd3ae}circle{fill:#b4adff}text{fill:#b8c0d0;font-size:10px}.progress .chart-note{margin:12px 0;font-size:.72rem}.empty{padding:26px 16px;background:#101620;border-radius:8px;color:#a7afc1;font-size:.85rem;line-height:1.6}summary{cursor:pointer;font-size:.8rem;min-height:36px;padding-top:10px;color:#c0c8d8}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:.75rem;text-align:left}th,td{padding:10px;border-bottom:1px solid #303746;font-variant-numeric:tabular-nums}.word-list{border-top:1px solid #303746;margin-top:12px}.word-list>div{padding:10px 0;border-bottom:1px solid #303746;font-size:.85rem}.word-list small{display:block;color:#a7afc1;font-size:.7rem;margin-top:4px}button:focus-visible,summary:focus-visible{outline:2px solid #c3bcff;outline-offset:3px}@media(hover:hover)and(pointer:fine){.map button:hover{border-color:#d7d1ff}}@media(max-width:1050px){.map{grid-template-columns:repeat(4,minmax(0,1fr))}.progress-heading{flex-direction:column}.numbers{grid-template-columns:repeat(4,auto);width:100%;gap:12px}}@media(max-width:600px){.progress{padding:16px}.map{grid-template-columns:repeat(2,minmax(0,1fr))}.map-head{align-items:flex-start;flex-direction:column;gap:6px}.numbers{grid-template-columns:repeat(2,auto)}.chart-head{flex-wrap:wrap}.map button{min-height:100px}svg{min-height:110px}}@media(prefers-reduced-motion:reduce){.map button{transition:none}}
</style>
